// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);

	stroke_color = 150
	background_color = 20
	background(background_color)
	strokeCap(PROJECT)

	frameRate(60)

	length_base = windowHeight / 2
	offset = windowHeight / 4
	y2 = windowHeight / 5
	margin = windowWidth / 6
	distance = 25

	rand_width = windowWidth / 100 
	rand_height = windowHeight / 20 

	old_distance = 0
	distance_slider = createSlider(5, 200, 25, 1)
	distance_slider.position(100, 10)
	distance_slider.size(windowWidth/6)

	fps_slider = createSlider(1, 60, 2, 1)
	fps_slider.position(100, 40)
	fps_slider.size(windowWidth/6)

	visible_slider = createSlider(0, 11, 4, 1)
	visible_slider.position(100, 70)
	visible_slider.size(windowWidth/6)

	polyline_slider = createSlider(0, 24, 12)
	polyline_slider.position(100, 100)
	polyline_slider.size(windowWidth/6)

	weight_slider = createSlider(1, 10, 3)
	weight_slider.position(100,130)
	weight_slider.size(windowWidth/6)

	deco_slider = createSlider(0, 50, 20)
	deco_slider.position(100, 160)
	deco_slider.size(windowWidth/6)

	size_slider = createSlider(1, rand_width*2, rand_width)
	size_slider.position(100, 190)
	size_slider.size(windowWidth/6)

	display = createP()
	display.style("color: white; line-height: 30px;")
	display.position(15, -12)
	display.html("Distance<br>FPS<br>Visible<br>Polyline<br>Weight<br>Deco<br>Size")		

	save_button = createButton('save');
	save_button.position(15,220)

	save_button.mousePressed(() => {
		saveCanvas("trafic.png")
	})

	checkbox = createCheckbox("loop")
	checkbox.style("color: white")
	checkbox.position(65, 220)

	checkbox.mousePressed(() => {
		if (checkbox.checked()) {
			draw()
		}
	})
}


function get_y2() {
	m = y2 + 0.5 * y2
	return random(m, y2)
}

function draw() {
	distance = distance_slider.value()
	fps = fps_slider.value()
	visible_rand = visible_slider.value()
	polyline_rand = polyline_slider.value()
	weight = weight_slider.value()
	deco_rand = deco_slider.value()
	size = size_slider.value()

	if (checkbox.checked()) {
		loop()
		frameRate(fps)
	}
	else {
		frameRate(60)
		if (old_distance == distance 
			&& old_visible_arnd == visible_rand 
			&& old_polyline_rand == polyline_rand 
			&& old_weight == weight 
			&& old_deco_rand == deco_rand
			&& old_size == size) {
			return
		}
	}

	background(background_color)

	for (let i = 0; i < windowWidth; i += distance){
		stroke(stroke_color)
		strokeWeight(weight)

		next = i + distance

		length_y1 = random(length_base) + offset
		length_y2 = get_y2() + offset

		if (visible_rand == 11) {
			visible = 1
		}
		else {
			visible = Math.round(random(visible_rand))
		}

			if (visible != 0) {
			line(i, length_y1, i, length_y2)
		}

		polyline = Math.round(random(polyline_rand))

		if (polyline == 1) {
			// 上線
			line(i, length_y1, next * random(1.5,2), length_y1)
		}
		else if (polyline == 2) {
			// 下線
			line(i, length_y2, next / random(1.5,2), length_y2)
		}

		if (deco_rand == 0) {
			deco = Math.round(random(1,4))
		}
		else if (deco_rand == 50) {
			deco = 0
		}
		else {
			deco = Math.round(random(deco_rand))
		}
		noStroke()
		fill(stroke_color)

		if (deco == 1) {
			circle(i, length_y1 * 0.65, random(1, size))
		}
		else if (deco == 2) {
			circle(i, length_y2 * 1.35, random(1, size))
		}
		else if (deco == 3) {
			rect(i-5, length_y1 * 0.65, random(1,size), random(10, size*1.5))
		}
		else if (deco == 4) {
			rect(i-5,  length_y2 * 1.45, random(1,size), random(10, size*1.5))
		}
	}

	noFill()
	stroke(background_color)
	strokeWeight(margin)
	rect(0, 0, 0, windowHeight)
	rect(windowWidth, 0, 0, windowHeight)

	old_distance = distance
	old_visible_arnd = visible_rand
	old_polyline_rand = polyline_rand
	old_weight = weight
	old_deco_rand = deco_rand
	old_size = size
}

